/**
 * CMMS contract (Phase 6 slice 6a; builder B). Inbound: calibrations and maintenance work orders with due dates (mirror
 * data classes CMMS_CALIBRATION and CMMS_MAINTENANCE; the equipment-use guard reads them).
 * Receiving commands (recipe-core 0950): plant.receive_cmms_calibration, plant.receive_cmms_maintenance.
 */
import { z } from 'zod';
import { CalendarDate, SourceCode, type SystemContract } from '../contract.ts';
import { EpochMicrosText } from '../envelope.ts';

export const CmmsCalibrationV1 = z.strictObject({
  equipmentCode: SourceCode,
  calibrationRef: SourceCode,
  performedAt: EpochMicrosText,
  result: z.enum(['PASS', 'FAIL', 'ADJUSTED_PASS']),
  dueOn: CalendarDate,
});
export const CmmsMaintenanceV1 = z.strictObject({
  equipmentCode: SourceCode,
  workOrder: SourceCode,
  kind: z.enum(['PREVENTIVE', 'CORRECTIVE']),
  status: z.enum(['OPEN', 'IN_PROGRESS', 'COMPLETED', 'CANCELLED']),
  dueOn: CalendarDate.nullable(),
});

export const CMMS: SystemContract = {
  system: 'CMMS',
  inbound: {
    'cmms.calibration': { summary: 'A calibration with its result and next due date', versions: { '1': CmmsCalibrationV1 } },
    'cmms.maintenance': { summary: 'A maintenance work order and its due date', versions: { '1': CmmsMaintenanceV1 } },
  },
  outbound: ['cmms.equipment_fault'],
  refusalCodes: {
    'EBMR-CMMS-001': 'WRONG_IDENTITY',
    'EBMR-CMMS-002': 'MALFORMED',
    'EBMR-CMMS-003': 'WRONG_IDENTITY',
    'EBMR-CMMS-004': 'STALE',
    'EBMR-CMMS-005': 'DUPLICATE',
    'EBMR-CMMS-006': 'OUT_OF_RANGE',
  },
};

/**
 * EMS contract (Phase 6 slice 6b-0; DI-49, DI-32, DI-31; D-P6b-6): environmental monitoring of Tablets rooms, the room
 * temperature and relative humidity only (differential pressure, particles and grades are Injectables, on the same
 * alarm log). The EMS is its own system with its own adapter (6a framework); its messages reuse the shapes of the
 * equipment data (equipment-data.ts) with subjectKind AREA and a room tag below. A feed gap is an alarm (outline 4.6:
 * the adapter framework's SEQUENCE_GAP, and the EMS's own FEED_GAP occurrence on the plant alarm log).
 *
 * Receiving commands (recipe-core 0960): plant.receive_series_chunk, plant.receive_equipment_alarm.
 */
import type { SystemContract } from '../contract.ts';
import { EquipmentAlarmV1, SeriesChunkV1 } from '../equipment-data.ts';
import { EQUIPMENT_DATA_REFUSALS } from './opcua.ts';

/** The room tags of the Tablets EMS (unit and fraction digits as the eBMR shows them). */
export const EMS_TAGS = [
  { tag: 'room.temp_C', unit: 'degC', scale: 1 },
  { tag: 'room.rh_pct', unit: '%RH', scale: 1 },
] as const;
export type EmsTag = (typeof EMS_TAGS)[number]['tag'];

export const EMS: SystemContract = {
  system: 'EMS',
  inbound: {
    'ems.series_chunk': { summary: 'Native temperature or humidity samples of one room sensor (subjectKind AREA)', versions: { '1': SeriesChunkV1 } },
    'ems.alarm': { summary: 'A room alarm raised, cleared or acknowledged at the EMS (limit excursion, feed gap)', versions: { '1': EquipmentAlarmV1 } },
  },
  outbound: [],
  refusalCodes: EQUIPMENT_DATA_REFUSALS,
};

/**
 * ERP/WMS contract (Phase 6 slice 6a; builder A). JSON with ISA-95/B2MML field names where they exist (D-P6a-2).
 * Inbound: production orders with their BOM, product and material masters, goods receipts with supplier batches
 * (PR-17), stock moves (PR-46), lot status and shipments (distribution records, 6d). Outbound (outbox topics): goods
 * issues, yields, lot status and stock blocks.
 */
import { z } from 'zod';
import { CalendarDate, SourceCode, SourceText, SourceValue, type SystemContract } from '../contract.ts';
import type { ErrorClass } from '../errors.ts';
import { EpochMicrosText } from '../envelope.ts';

export const ErpBomLine = z.strictObject({ materialCode: SourceCode, quantity: SourceValue });

/**
 * Slice 6a builder A added optional fields (additive, version 1 unchanged for existing senders): the receiving command
 * (site services 0913) needs them to apply the message, and refuses it as MALFORMED (EBMR-ERP-001) without them.
 */
export const ErpProductionOrderV1 = z.strictObject({
  orderNumber: SourceCode,
  productCode: SourceCode,
  /** Needed by the receiving command (the order is for one strength of the product). */
  strength: SourceText.optional(),
  plannedQuantity: SourceValue,
  bom: z.array(ErpBomLine).min(1).max(500),
  plannedStart: EpochMicrosText,
});
export const MATERIAL_KINDS = ['API', 'EXCIPIENT', 'PRIMARY_PACKAGING', 'PRINTED_PACKAGING', 'INTERMEDIATE', 'FINISHED'] as const;
const WholeMonths = z.string().regex(/^[1-9][0-9]{0,2}$/, 'whole months as text');
export const ErpMaterialMasterV1 = z.strictObject({
  materialCode: SourceCode,
  name: SourceText,
  baseUnit: SourceValue.shape.unit,
  /** Needed by the receiving command (QA confirms a new or changed kind, site services 0802). */
  materialKind: z.enum(MATERIAL_KINDS).optional(),
  maxRetestMonths: WholeMonths.optional(),
});
export const ErpProductMasterV1 = z.strictObject({
  productCode: SourceCode,
  name: SourceText,
  strength: SourceText,
  /** Needed by the receiving command. */
  betaLactam: z.boolean().optional(),
  shelfLifeMonths: WholeMonths.optional(),
  reprocessingPermitted: z.boolean().optional(),
});

/** One supplier batch of a delivery: becomes one lot (PR-17). */
export const WmsSupplierBatch = z.strictObject({
  supplierLot: SourceCode,
  manufacturerCode: SourceCode,
  containers: z.string().regex(/^[1-9][0-9]{0,5}$/),
  quantity: SourceValue,
  /** Required by the receiving command (a lot is received with its expiry, PR-18); null is refused as MALFORMED. */
  expiryDate: CalendarDate.nullable(),
  retestDate: CalendarDate.nullable().optional(),
});
export const WmsGoodsReceiptV1 = z.strictObject({
  deliveryId: SourceCode,
  materialCode: SourceCode,
  supplierCode: SourceCode,
  supplierBatches: z.array(WmsSupplierBatch).min(1).max(100),
  receivedAt: EpochMicrosText,
  /** The name on the delivery note (part of the receipt record, PR-17). */
  deliveryNoteName: SourceText.optional(),
});
/** A move the WMS reports; one that already happened against the location rule raises an alarm (D-P6a-7). */
export const WmsStockMoveV1 = z.strictObject({
  lotNumber: SourceCode,
  fromLocation: SourceCode,
  toLocation: SourceCode,
  toLocationKind: z.enum(['QUARANTINE', 'RELEASED', 'REJECTED', 'PRODUCTION', 'RETURNS']),
  quantity: SourceValue,
  movedAt: EpochMicrosText,
});
export const WmsLotStatusV1 = z.strictObject({ lotNumber: SourceCode, status: z.enum(['QUARANTINE', 'RELEASED', 'REJECTED', 'BLOCKED']) });
export const ErpShipmentV1 = z.strictObject({
  shipmentId: SourceCode,
  lotNumber: SourceCode,
  consigneeCode: SourceCode,
  consigneeName: SourceText,
  consigneeAddress: SourceText,
  quantity: SourceValue,
  shippedAt: EpochMicrosText,
  /** Slice 6d (additive): the market shipped to; required when the finished lot is made for more than one market. */
  market: z.enum(['IN', 'US', 'EU']).optional(),
  /** Slice 6d (additive): shipped in quarantine to a contract partner (INV-42); false when left out. */
  quarantine: z.boolean().optional(),
});

/**
 * The EBMR codes the receiving command (site.erp_wms_receive, site services 0913) and the domain commands it calls raise,
 * with their class. A code missing here is unclassified: the worker alarms and does not retry it.
 */
export const ERP_WMS_REFUSAL_CODES: Readonly<Record<string, ErrorClass>> = {
  'EBMR-ERP-001': 'MALFORMED',
  // Distribution records (site services 0961, slice 6d) and the shipping interlock (0870) the shipment goes through.
  'EBMR-ERP-020': 'MALFORMED',
  'EBMR-ERP-021': 'WRONG_IDENTITY',
  'EBMR-ERP-022': 'OUT_OF_RANGE',
  'EBMR-SHP-002': 'OUT_OF_RANGE',
  'EBMR-SHP-003': 'DUPLICATE',
  'EBMR-SHP-004': 'OUT_OF_RANGE',
  'EBMR-ERP-002': 'WRONG_IDENTITY',
  'EBMR-ERP-003': 'OUT_OF_RANGE',
  'EBMR-ERP-004': 'STALE',
  'EBMR-ERP-010': 'WRONG_IDENTITY',
  // Receipt (site services 0750, 0910) and the location rule (0911).
  'EBMR-SITE-104': 'OUT_OF_RANGE',
  'EBMR-SITE-105': 'WRONG_IDENTITY',
  'EBMR-SITE-171': 'WRONG_IDENTITY',
  'EBMR-SITE-172': 'WRONG_IDENTITY',
  'EBMR-SITE-914': 'MALFORMED',
  'EBMR-SITE-915': 'OUT_OF_RANGE',
  'EBMR-SITE-919': 'MALFORMED',
  // Masters and orders (site services 0802).
  'EBMR-SITE-170': 'MALFORMED',
  'EBMR-SITE-175': 'MALFORMED',
  'EBMR-SITE-176': 'MALFORMED',
  'EBMR-SITE-340': 'MALFORMED',
};

/** One pending outbound message as site.erp_outbound_pending lists it (site services 0912). */
export const ErpOutboundMessage = z.strictObject({
  messageId: z.uuid(),
  topic: z.enum(['erp.goods_issue', 'erp.yield', 'erp.lot_status', 'erp.stock_block']),
  lotId: z.uuid(),
  payload: z.record(z.string(), z.unknown()),
  attempts: z.string().regex(/^(0|[1-9][0-9]*)$/),
  createdAtUs: EpochMicrosText,
});
export type ErpOutboundMessage = z.infer<typeof ErpOutboundMessage>;

export const ERP_WMS: SystemContract = {
  system: 'ERP_WMS',
  inbound: {
    'erp.production_order': { summary: 'A production order with its BOM (compared with the MBR BOM at issue)', versions: { '1': ErpProductionOrderV1 } },
    'erp.material_master': { summary: 'A material master (QA confirms before use)', versions: { '1': ErpMaterialMasterV1 } },
    'erp.product_master': { summary: 'A product master (QA confirms before use)', versions: { '1': ErpProductMasterV1 } },
    'wms.goods_receipt': { summary: 'A delivery with its supplier batches (one lot each, PR-17)', versions: { '1': WmsGoodsReceiptV1 } },
    'wms.stock_move': { summary: 'A stock move between locations (PR-46)', versions: { '1': WmsStockMoveV1 } },
    'wms.lot_status': { summary: 'The WMS status of a lot (mirror data class ERP_LOT_STATUS)', versions: { '1': WmsLotStatusV1 } },
    'erp.shipment': { summary: 'A shipment of a finished lot to a consignee (distribution record, 6d)', versions: { '1': ErpShipmentV1 } },
  },
  outbound: ['erp.goods_issue', 'erp.yield', 'erp.lot_status', 'erp.stock_block'],
  refusalCodes: ERP_WMS_REFUSAL_CODES,
};

/**
 * Serialisation L3/L4 contract (Phase 6 slice 6c; PR-42; outline 4.6, L-53; default D-P6c-1). The device-side pool
 * contract (pool requests, serial state events, the hashed pool report) stays in ../../serialisation; this module is
 * what the L3 system sends the eBMR through the adapter framework, a documented JSON shape modelled on the OPEN-SCS
 * event names and the EPCIS aggregation event (a vendor's exact profile is mapped at deployment, D-P6c-1):
 *
 *   l3.aggregation        an EPCIS-style AggregationEvent: a parent (the shipper's SSCC) with the count of serialised
 *                         packs aggregated into it (ADD) or taken out (DELETE), for one pool. The record holds each
 *                         shipper's SSCC and packs (TB-24 SHIPPER entries); a parent that is no shipper of the pool's
 *                         packaging order is refused WRONG_IDENTITY, a count that differs from the shipper's packs is
 *                         refused OUT_OF_RANGE (the aggregation mismatch).
 *   l3.decommission_task  a decommissioning task the L3 system opened when a pool's lot or packs were rejected (OPEN), or
 *                         closed when its serials were decommissioned (DONE). An OPEN task keeps release blocked (PR-42).
 *
 * Unit serials never enter the record (L-53): both messages carry counts. The L3 mirror data class L3_SERIAL_STATUS
 * (blocking) is kept fresh by the adapter's heartbeat; in MIRROR mode release fails closed when it is stale.
 * Receiving command (tablets 1231): tab.receive_l3_message.
 */
import { z } from 'zod';
import { SourceCode, SourceText, type SystemContract } from '../contract.ts';
import { EpochMicrosText } from '../envelope.ts';

/** A count as decimal text (no leading zeros). */
const CountText = z.string().regex(/^(0|[1-9][0-9]{0,17})$/, 'a whole count as text');
/** An SSCC (GS1 AI 00): 18 digits. */
export const Sscc = z.string().regex(/^[0-9]{18}$/, 'an SSCC of 18 digits');

export const L3AggregationV1 = z.strictObject({
  eventId: SourceCode,
  action: z.enum(['ADD', 'DELETE']),
  poolId: SourceCode,
  parentId: Sscc,
  childCount: CountText,
  eventTime: EpochMicrosText,
});
export type L3AggregationV1 = z.infer<typeof L3AggregationV1>;

export const L3DecommissionTaskV1 = z.strictObject({
  taskId: SourceCode,
  poolId: SourceCode,
